import{_ as n,l as r,o as e,c as p,v as o,p as s,x as l,d as i,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"SDN 与 OpenFlow","description":"","frontmatter":{"title":"SDN 与 OpenFlow","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sdn-openflow.md","filePath":"cs/sdn-openflow.md","lastUpdated":1789023840000}'),h={name:"cs/sdn-openflow.md"};function _(m,a,S,f,D,P){const t=r("Mermaid");return e(),p("div",null,[a[1]||(a[1]=o('<h1 id="sdn-与-openflow" tabindex="-1">SDN 与 OpenFlow <a class="header-anchor" href="#sdn-与-openflow" aria-label="Permalink to &quot;SDN 与 OpenFlow&quot;">​</a></h1><div class="epigraph"><p>控制面从盒内协议簇里抽到控制器，交换机按流表匹配-动作转发；OpenFlow 是这条南向的一个历史接口。</p><footer>—— 据 McKeown et al., OpenFlow, ACM SIGCOMM CCR 2008；RFC 7426 SDN 层整理</footer></div><p><a href="/cs/tcam-lookup">上一课</a> 给出流表的硬件形状。传统盒内 BGP/OSPF 自闭环。缺口是 <strong>SDN 分工</strong>：控制器算全局，南向装表。本课不把 P4 语言写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TE 与 ACL 在分布式协议里用属性暗示，难全局最优。SDN：逻辑中心看全拓扑，下发精确匹配。OpenFlow：匹配域（端口、MAC、IP、TCP）→ 动作（出端口、改头、去控制器）。失败模式：控制器分区、表满、反应式首包上送变成慢路径洪水。与 RR 对照：都是控制面中心化，OpenFlow 更细到每流。</p><p>不要把 SDN 写成「不用 BGP」的互联网替代：域间仍政策。</p><p><span class="marginnote">OpenFlow 交换机规范多版本。RFC 7426 分层。本课不把每个 match 字段列完。</span></p><h3 id="南向之一不是互联网替代" tabindex="-1">南向之一不是互联网替代 <a class="header-anchor" href="#南向之一不是互联网替代" aria-label="Permalink to &quot;南向之一不是互联网替代&quot;">​</a></h3><p>控制器装流表，交换机匹配-动作。表满与控制器分区是失败模式。域间仍政策。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：控制器 → OpenFlow → 多级流表 → 流水线。对照 RIB/FIB：控制器相当于外置 RP。主动装表 vs 首包上送。</p>',11)),(e(),s(c,null,{default:l(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTL%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%20--%3E%20OF%5B%22OpenFlow%22%5D%0A%20%20OF%20--%3E%20FT%5B%22%E6%B5%81%E8%A1%A8%20TCAM%22%5D%0A%20%20FT%20--%3E%20FWD%5B%22%E5%8C%B9%E9%85%8D%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20MISS%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20CTL%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数据中心 Clos 可用 SDN 做负载与租户隔离，或用 BGP EVPN 做同一件事——两条工程路径。PFC 仍在数据面。安全：控制器被冒充则全网被改，南向要 TLS，对象与 BGP 认证同类。</p><p>与 Saltzer：中心控制是性能与政策优化，正确性仍要端到端。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 OVSDB/NETCONF 的全部。P4 可编程是下一课。后课默认：SDN = 控制/转发分离；OpenFlow 是南向之一。</p><p>反应式 SDN 在广域高 RTT（卫星）上首包延迟不可接受，应主动装表。</p><p>上一课留下的缺口在本课收口；「SDN 与 OpenFlow」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/p4-programmable">P4 可编程</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制器装流表，交换机执行匹配-动作。</li><li>表容量与控制器可用是边界。</li><li>不自动取消域间 BGP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：McKeown et al., 2008；RFC 7426。</li></ul>',10))])}const C=n(h,[["render",_]]);export{u as __pageData,C as default};
